INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (2, 0, 73, 2, 1, 0.0, 1, "ティア", 0.0, 140301, "あんたにとって\nプリンセスって誰なの？", -363.0);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (3, 1, 73, 5, 2, 1.384, 2, "ティア", 0.0, 140301, "ちょっ……なによ\nセクハラすんじゃないわよ\nほら、早く選びなさいよ", -363.0);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (5, 1, 73, 5, 3, 0.0, 3, "ティア", 0.0, 140301, "……～っ……\nや、やめなさいっての\nくすぐったいんだから……", -363.0);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (5, 1, 73, 3, 4, 6.175, 4, "ティア", 0.0, 140301, "……あんた。\nあたしをからかってるの？\nそ、それとも……", -363.0);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (4, 1, 73, 4, 5, 0.0, 5, "ティア", 0.0, 140301, "あたしを選ぼう、とか……\n言わないわよね……？", -363.0);
